fid = fopen([chromosome 'probeDomainStartsAndEnds.txt'], 'r');
tline = fgetl(fid);
i = 0;
while ischar(tline)
    i = i+1;
    C = strsplit(tline);
    DomainStart(i) = str2num(C{2});
    DomainEnd(i) = str2num(C{3});
    BinCenter(i) = (DomainStart(i)+DomainEnd(i))/2;
    tline = fgetl(fid);
end
fclose(fid);

%%%%%% modify here to get correct bins - filteredTable chrI = rows 1-302, chrII =
%%%%%% rows 303-608
for i = 1:14
    BinIDs = [];
    for j = 1:302
        if BinCenters(j)>DomainStart(i) && BinCenters(j)<DomainEnd(i)
            BinIDs = [BinIDs j];
        end
    end
    ChosenBinID(i,:) = [min(BinIDs) max(BinIDs)];
end

for i = 15:28
    BinIDs = [];
    for j = 303:608
        if BinCenters(j)>DomainStart(i) && BinCenters(j)<DomainEnd(i)
            BinIDs = [BinIDs j];
        end
    end
    ChosenBinID(i,:) = [min(BinIDs) max(BinIDs)];
end


for i = 1:TotalTADNum
    for j = 1:TotalTADNum
        HiC_chosen(i, j) = sum(sum(HiC_chrIchrII(ChosenBinID(i,1):ChosenBinID(i,2),ChosenBinID(j,1):ChosenBinID(j,2))));
        HiC_chosen(i, j) = HiC_chosen(i, j)/(ChosenBinID(i,2)-ChosenBinID(i,1)+1)/(ChosenBinID(j,2)-ChosenBinID(j,1)+1);
    end
end

for i = 1:length(HiC_chosen)
    HiC_chosen(i, i) = 0;
end
for i = 1:length(HiC_chosen)
    HiC_chosen(i, i) = max(max(HiC_chosen));
end

