%% load chromosome tracing cluster matrices and compare to HiC
cluster_corr = zeros(1:length(NumClusters));

figure('Renderer', 'painters', 'Position', [10 10 800 1000])
for cluster = 1:NumClusters

    load(['../sub0res06_sub1res08/ChrClus' num2str(cluster) '.mat'])%load traces
    load(['../sub0res06_sub1res08/DisListClus' num2str(cluster) '.mat'])%load DisList
    
    Median = zeros(TotalTADNum,TotalTADNum);

    for i = 1:TotalTADNum
        for j = 1:TotalTADNum
            DisList = [];
            for k = 1:length(ChrClus)
                if ChrClus(k).r(i) == 1 && ChrClus(k).r(j) == 1
                    if ((ChrClus(k).x(i)-ChrClus(k).x(j))^2+(ChrClus(k).y(i)-ChrClus(k).y(j))^2+(ChrClus(k).z(i)-ChrClus(k).z(j))^2)^0.5 <=6
                        DisList = [DisList ((ChrClus(k).x(i)-ChrClus(k).x(j))^2+(ChrClus(k).y(i)-ChrClus(k).y(j))^2+(ChrClus(k).z(i)-ChrClus(k).z(j))^2)^0.5];
                    end
                end
            end

            Median(i,j) = median(DisList);
        end
    end
    
    GenomicDis = zeros(TotalTADNum,TotalTADNum);
    GenomicDis_pxl = [];
    HiC_pxl = [];
    Dis_pxl = [];

    % CloseProb_pxl = [];
    % CloseThresh = 0.5;
    for i = 1:TotalTADNum
        for j = 1:TotalTADNum
            GenomicDis(i,j) = abs(BinCenter(i)-BinCenter(j));
            if i~= j
                GenomicDis_pxl = [GenomicDis_pxl GenomicDis(i,j)];
                HiC_pxl = [HiC_pxl HiC_chosen(i,j)];
                Dis_pxl = [Dis_pxl Median(i,j)];
                % CloseProb_pxl = [CloseProb_pxl length(find(DisListAll{i,j}<CloseThresh))/length(DisListAll{i,j})];
            end
        end
    end

    subplot(4, round(NumClusters/4), cluster)
    loglog(Dis_pxl, 1./HiC_pxl, 'o','MarkerSize', 5, 'MarkerEdgeColor', 'k', 'MarkerFaceColor', 'w');
    xlabel('median distance (um)');
    ylabel('inverse contact frequency');
    hold on
    axis square
    Ind = find(HiC_pxl>0);
    x = log(Dis_pxl(Ind))';
    y = log(1./HiC_pxl(Ind))';
    X = [ones(size(x)), x];
    [b, bint] = regress(y,X);
    R = corrcoef(x, y);
    %title([chromosome ' cluster ' num2str(cluster) ' R = ' num2str(R(2,1))])
    %title(['cluster ' num2str(cluster) ' R = ' num2str(round(R(2,1),2))])
    title(['cluster ' num2str(cluster)])
    x = Dis_pxl';
    y_fit = exp(b(1))*x.^b(2);
    loglog(x, y_fit, '-r','LineWidth', 2);
    grid on
    hold off
    set(gca,'fontsize', 8);
    
    cluster_corr(1,cluster) = R(2,1);

end

