    [b, bint] = regress(y,X);
    R = corrcoef(x, y);
    %title([chromosome ' cluster ' num2str(cluster) ' R = ' num2str(R(2,1))])
    title(['cluster ' num2str(cluster) ' R = ' num2str(round(R(2,1),2))])
    x = Dis_pxl';
    y_fit = exp(b(1))*x.^b(2);
    loglog(x, y_fit, '-r','LineWidth', 2);
    grid on
    hold off
    set(gca,'fontsize', 8);
    
    cluster_corr_inter(1,cluster) = R(2,1);

end

